function evaluateEvent({
    api,
    event
}) {
    const payload = api.context.props.payload;
    const id = payload.type.id;
    let params = {};
    let route = null;

    function getChecklistCardItems(payload) {
        const formatProgressBar = function(items) {
            if (!items.length) return [];
            return items.map(function(item) {
                return {
                    "icon": item.props_details.header_icon,
                    "title": item.title,
                    "status": item.status && item.status.toLowerCase() || "start",
                    "children": formatProgressBar(item.children)
                };
            });
        };

        const checklistItems = formatProgressBar(payload.children);
        checklistItems.forEach(function(item) {
            const numOfCompletedItems = item.children.filter(function(item) {
                return item.status == 'complete';
            }).length;
            const totalItems = item.children.length;
            item.percentage = totalItems ? (numOfCompletedItems / totalItems) * 100 : 0;
        });
        return checklistItems;
    }

    function renameTypeKey(payload, oldKey, newKey) {
        const {
            [oldKey]: replaceByKey, ...rest
        } = payload;
        return {
            ...rest,
            [newKey]: replaceByKey
        };
    }

    switch (id) {
        case 'fe9a6f08ebf4011090fa99602a522838':
            {
                route = 'one-col-section';
                params = {
                    payload: renameTypeKey(payload, 'type', 'ctype')
                };
                break;
            }
        case 'cca52344ebf4011090fa99602a522855':
            {
                route = 'two-col-section';
                params = {
                    payload: renameTypeKey(payload, 'type', 'ctype')
                };
                break;
            }
        case '215aebc4ebf4011090fa99602a5228b7':
            {
                route = 'three-col-section';
                params = {
                    payload: renameTypeKey(payload, 'type', 'ctype')
                };
                break;
            }
        case '13721944eb81011090fa99602a52283c':
            {
                route = 'flex-col-section';
                params = {
                    payload: renameTypeKey(payload, 'type', 'ctype')
                };
                break;
            }
        case '115fe59ceb38011090fa99602a5228b5':
            {
                route = 'simple_card_with_button';
                params = {
                    payload: renameTypeKey(payload, 'type', 'ctype')
                };
                break;
            }
        case 'fd78a98d531501102958ddeeff7b12c0':
            {
                route = 'checklist-card';
                params = {
                    payload: getChecklistCardItems(payload)
                };
                break;
            }
        case '9f3b9c0187410110a4a2c077f6cb0bd3':
            {
                route = 'breadcrumbs';
                params = {
                    payload: renameTypeKey(payload, 'type', 'ctype')
                };
                break;
            }
        case '59684a39c3e401104b8e88c7c840ddd1':
            {
                route = 'card_content';
                params = {
                    cardProps: renameTypeKey(payload, 'type', 'ctype')
                };
                break;
            }
        case '06c307f4a1018110f87785eefa5ec94d':
            {
                route = 'content-tree';
                params = {
                    contentTreeProps: renameTypeKey(payload, 'type', 'ctype')
                };
                break;
            }
        case '9b495ee5a1c50510f87785eefa5ec933':
            {
                route = 'list-content-block';
                params = {
                    listProps: renameTypeKey(payload, 'type', 'ctype')
                };
                break;
            }
        case '3ad1e8b0eb110110d05213b34752286a':
            {
                route = 'plugin_installer';
                params = {
                    Data: payload
                };
                break;
            }
        case 'ce99c63da1054510f87785eefa5ec961':
            {
                route = 'record-content-block';
                params = {
                    recordProps: renameTypeKey(payload, 'type', 'ctype')
                };
                break;
            }
    }

    return {
        viewportElementId: 'viewport_anb',
        route: route,
        params: params
    };
}

